-- 0001_core: organisation and master data.
--
-- Conventions used by every migration in this directory:
--   * snake_case names, UUID primary keys generated by the application
--   * quantities            numeric(18,3)  tons and kilograms
--   * rates and percentages numeric(12,3)
--   * conversion factors    numeric(18,6)
--   * every mutable table carries created_at/created_by/updated_at/updated_by
--     and row_version for optimistic concurrency
--   * master data is deactivated, never deleted, so transactional history
--     never loses its references

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- Reusable column groups are written out in full rather than hidden behind a
-- domain or a composite type, so that a DBA reading one table sees everything.

CREATE TABLE companies (
    id           uuid PRIMARY KEY,
    code         text NOT NULL,
    name         text NOT NULL,
    currency     char(3) NOT NULL DEFAULT 'USD',
    time_zone    text NOT NULL DEFAULT 'Asia/Phnom_Penh',
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT companies_code_key UNIQUE (code),
    CONSTRAINT companies_validity_ck CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE TABLE factories (
    id           uuid PRIMARY KEY,
    company_id   uuid NOT NULL REFERENCES companies (id),
    code         text NOT NULL,
    name         text NOT NULL,
    time_zone    text NOT NULL DEFAULT 'Asia/Phnom_Penh',
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT factories_code_key UNIQUE (code)
);
CREATE INDEX factories_company_idx ON factories (company_id) WHERE active;

CREATE TABLE production_areas (
    id           uuid PRIMARY KEY,
    factory_id   uuid NOT NULL REFERENCES factories (id),
    code         text NOT NULL,
    name         text NOT NULL,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT production_areas_code_key UNIQUE (factory_id, code)
);

CREATE TABLE production_lines (
    id           uuid PRIMARY KEY,
    factory_id   uuid NOT NULL REFERENCES factories (id),
    area_id      uuid REFERENCES production_areas (id),
    code         text NOT NULL,
    name         text NOT NULL,
    stage        text NOT NULL,
    rated_tph    numeric(12,3) NOT NULL DEFAULT 0,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT production_lines_code_key UNIQUE (code),
    CONSTRAINT production_lines_rate_ck CHECK (rated_tph >= 0),
    CONSTRAINT production_lines_stage_ck CHECK (stage IN
        ('CANE','RAW_SUGAR','REMELT','REFINING','PACKING','SHIPMENT'))
);
CREATE INDEX production_lines_factory_idx ON production_lines (factory_id) WHERE active;

CREATE TABLE stations (
    id           uuid PRIMARY KEY,
    line_id      uuid NOT NULL REFERENCES production_lines (id),
    code         text NOT NULL,
    name         text NOT NULL,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT stations_code_key UNIQUE (line_id, code)
);

CREATE TABLE shifts (
    id           uuid PRIMARY KEY,
    factory_id   uuid NOT NULL REFERENCES factories (id),
    code         text NOT NULL,
    name         text NOT NULL,
    start_time   time NOT NULL DEFAULT '00:00',
    hours        numeric(5,2) NOT NULL DEFAULT 8,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT shifts_code_key UNIQUE (code),
    CONSTRAINT shifts_hours_ck CHECK (hours > 0 AND hours <= 24)
);

-- The work calendar marks days that are not available for crushing. The plan
-- generator skips them and extends the campaign instead of cutting tonnage.
CREATE TABLE work_calendar_days (
    id            uuid PRIMARY KEY,
    factory_id    uuid NOT NULL REFERENCES factories (id),
    business_date date NOT NULL,
    day_type      text NOT NULL DEFAULT 'WORKING',
    note          text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    created_by    text NOT NULL,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    updated_by    text NOT NULL,
    row_version   bigint NOT NULL DEFAULT 1,
    CONSTRAINT work_calendar_days_key UNIQUE (factory_id, business_date),
    CONSTRAINT work_calendar_days_type_ck CHECK (day_type IN ('WORKING','SHUTDOWN','MAINTENANCE','HOLIDAY'))
);

CREATE TABLE product_categories (
    id           uuid PRIMARY KEY,
    code         text NOT NULL,
    name         text NOT NULL,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT product_categories_code_key UNIQUE (code)
);

CREATE TABLE units_of_measure (
    id           uuid PRIMARY KEY,
    code         text NOT NULL,
    name         text NOT NULL,
    dimension    text NOT NULL,
    decimals     integer NOT NULL DEFAULT 3,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT units_of_measure_code_key UNIQUE (code),
    CONSTRAINT units_of_measure_decimals_ck CHECK (decimals BETWEEN 0 AND 6),
    CONSTRAINT units_of_measure_dimension_ck CHECK (dimension IN ('MASS','COUNT','VOLUME','TIME','LENGTH'))
);

CREATE TABLE products (
    id            uuid PRIMARY KEY,
    code          text NOT NULL,
    name          text NOT NULL,
    category_code text NOT NULL REFERENCES product_categories (code),
    base_uom      text NOT NULL REFERENCES units_of_measure (code),
    stage         text NOT NULL DEFAULT 'REFINING',
    storage_class text NOT NULL DEFAULT 'FINISHED',
    is_finished   boolean NOT NULL DEFAULT true,
    valid_from    date,
    valid_to      date,
    active        boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    created_by    text NOT NULL,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    updated_by    text NOT NULL,
    row_version   bigint NOT NULL DEFAULT 1,
    CONSTRAINT products_code_key UNIQUE (code),
    CONSTRAINT products_storage_class_ck CHECK (storage_class IN ('RAW','FINISHED','MATERIAL')),
    CONSTRAINT products_stage_ck CHECK (stage IN
        ('CANE','RAW_SUGAR','REMELT','REFINING','PACKING','SHIPMENT'))
);
CREATE INDEX products_category_idx ON products (category_code) WHERE active;

-- A conversion with product_id NULL applies to every product.
CREATE TABLE uom_conversions (
    id           uuid PRIMARY KEY,
    product_id   uuid REFERENCES products (id),
    from_uom     text NOT NULL REFERENCES units_of_measure (code),
    to_uom       text NOT NULL REFERENCES units_of_measure (code),
    factor       numeric(18,6) NOT NULL,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT uom_conversions_factor_ck CHECK (factor > 0),
    CONSTRAINT uom_conversions_distinct_ck CHECK (from_uom <> to_uom)
);
-- Two partial unique indexes because NULL product_id must still be unique.
CREATE UNIQUE INDEX uom_conversions_product_key ON uom_conversions (product_id, from_uom, to_uom)
    WHERE product_id IS NOT NULL;
CREATE UNIQUE INDEX uom_conversions_global_key ON uom_conversions (from_uom, to_uom)
    WHERE product_id IS NULL;

CREATE TABLE packaging_types (
    id            uuid PRIMARY KEY,
    code          text NOT NULL,
    name          text NOT NULL,
    net_weight_kg numeric(12,3) NOT NULL,
    material_id   uuid,
    valid_from    date,
    valid_to      date,
    active        boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    created_by    text NOT NULL,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    updated_by    text NOT NULL,
    row_version   bigint NOT NULL DEFAULT 1,
    CONSTRAINT packaging_types_code_key UNIQUE (code),
    CONSTRAINT packaging_types_weight_ck CHECK (net_weight_kg > 0)
);

CREATE TABLE warehouses (
    id              uuid PRIMARY KEY,
    factory_id      uuid NOT NULL REFERENCES factories (id),
    code            text NOT NULL,
    name            text NOT NULL,
    storage_class   text NOT NULL,
    capacity_tons   numeric(18,3) NOT NULL DEFAULT 0,
    usable_pct      numeric(6,3) NOT NULL DEFAULT 100,
    opening_balance numeric(18,3) NOT NULL DEFAULT 0,
    is_silo         boolean NOT NULL DEFAULT false,
    valid_from      date,
    valid_to        date,
    active          boolean NOT NULL DEFAULT true,
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      text NOT NULL,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    updated_by      text NOT NULL,
    row_version     bigint NOT NULL DEFAULT 1,
    CONSTRAINT warehouses_code_key UNIQUE (code),
    CONSTRAINT warehouses_capacity_ck CHECK (capacity_tons >= 0),
    CONSTRAINT warehouses_usable_ck CHECK (usable_pct > 0 AND usable_pct <= 100),
    CONSTRAINT warehouses_opening_ck CHECK (opening_balance >= 0),
    CONSTRAINT warehouses_class_ck CHECK (storage_class IN ('RAW','FINISHED','MATERIAL'))
);
CREATE INDEX warehouses_factory_idx ON warehouses (factory_id, storage_class) WHERE active;

CREATE TABLE storage_zones (
    id            uuid PRIMARY KEY,
    warehouse_id  uuid NOT NULL REFERENCES warehouses (id),
    code          text NOT NULL,
    name          text NOT NULL,
    capacity_tons numeric(18,3) NOT NULL DEFAULT 0,
    active        boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    created_by    text NOT NULL,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    updated_by    text NOT NULL,
    row_version   bigint NOT NULL DEFAULT 1,
    CONSTRAINT storage_zones_code_key UNIQUE (warehouse_id, code),
    CONSTRAINT storage_zones_capacity_ck CHECK (capacity_tons >= 0)
);

CREATE TABLE customers (
    id           uuid PRIMARY KEY,
    code         text NOT NULL,
    name         text NOT NULL,
    country      text,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT customers_code_key UNIQUE (code)
);

-- Shipment channels replace the per-trader columns of the source workbook, so
-- adding a customer is master data maintenance rather than a schema change.
CREATE TABLE shipment_channels (
    id           uuid PRIMARY KEY,
    code         text NOT NULL,
    name         text NOT NULL,
    customer_id  uuid REFERENCES customers (id),
    category     text NOT NULL DEFAULT 'DOMESTIC',
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT shipment_channels_code_key UNIQUE (code),
    CONSTRAINT shipment_channels_category_ck CHECK (category IN ('QUOTA','EXPORT','DOMESTIC','INTERNAL'))
);

CREATE TABLE materials (
    id              uuid PRIMARY KEY,
    code            text NOT NULL,
    name            text NOT NULL,
    uom             text NOT NULL REFERENCES units_of_measure (code),
    safety_stock    numeric(18,3) NOT NULL DEFAULT 0,
    lead_time_days  integer NOT NULL DEFAULT 0,
    scrap_pct       numeric(6,3) NOT NULL DEFAULT 0,
    on_hand         numeric(18,3) NOT NULL DEFAULT 0,
    on_order        numeric(18,3) NOT NULL DEFAULT 0,
    valid_from      date,
    valid_to        date,
    active          boolean NOT NULL DEFAULT true,
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      text NOT NULL,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    updated_by      text NOT NULL,
    row_version     bigint NOT NULL DEFAULT 1,
    CONSTRAINT materials_code_key UNIQUE (code),
    CONSTRAINT materials_safety_ck CHECK (safety_stock >= 0),
    CONSTRAINT materials_lead_ck CHECK (lead_time_days >= 0),
    CONSTRAINT materials_scrap_ck CHECK (scrap_pct >= 0 AND scrap_pct < 100),
    CONSTRAINT materials_stock_ck CHECK (on_hand >= 0 AND on_order >= 0)
);

ALTER TABLE packaging_types
    ADD CONSTRAINT packaging_types_material_fk FOREIGN KEY (material_id) REFERENCES materials (id);

-- Consumption of a material per ton of packed product, used by requirement
-- planning for everything that is not the primary bag (liners, thread, labels).
CREATE TABLE packaging_bom (
    id              uuid PRIMARY KEY,
    packaging_id    uuid NOT NULL REFERENCES packaging_types (id),
    material_id     uuid NOT NULL REFERENCES materials (id),
    qty_per_package numeric(18,6) NOT NULL,
    active          boolean NOT NULL DEFAULT true,
    created_at      timestamptz NOT NULL DEFAULT now(),
    created_by      text NOT NULL,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    updated_by      text NOT NULL,
    row_version     bigint NOT NULL DEFAULT 1,
    CONSTRAINT packaging_bom_key UNIQUE (packaging_id, material_id),
    CONSTRAINT packaging_bom_qty_ck CHECK (qty_per_package > 0)
);

CREATE TABLE reason_codes (
    id           uuid PRIMARY KEY,
    code         text NOT NULL,
    name         text NOT NULL,
    category     text NOT NULL,
    valid_from   date,
    valid_to     date,
    active       boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now(),
    created_by   text NOT NULL,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    updated_by   text NOT NULL,
    row_version  bigint NOT NULL DEFAULT 1,
    CONSTRAINT reason_codes_code_key UNIQUE (code),
    CONSTRAINT reason_codes_category_ck CHECK (category IN
        ('VARIANCE','LOSS','ADJUSTMENT','DOWNTIME','REJECTION','REWORK','STOCK_CORRECTION'))
);

CREATE TABLE equipment (
    id            uuid PRIMARY KEY,
    factory_id    uuid NOT NULL REFERENCES factories (id),
    line_id       uuid REFERENCES production_lines (id),
    code          text NOT NULL,
    name          text NOT NULL,
    rated_tph     numeric(12,3) NOT NULL DEFAULT 0,
    active        boolean NOT NULL DEFAULT true,
    created_at    timestamptz NOT NULL DEFAULT now(),
    created_by    text NOT NULL,
    updated_at    timestamptz NOT NULL DEFAULT now(),
    updated_by    text NOT NULL,
    row_version   bigint NOT NULL DEFAULT 1,
    CONSTRAINT equipment_code_key UNIQUE (code),
    CONSTRAINT equipment_rate_ck CHECK (rated_tph >= 0)
);
